#!/usr/bin/env python3
"""Simple CLI todo list tool."""

import json
import sys
import os
from pathlib import Path

TODO_FILE = Path.home() / ".todos.json"

def load_todos():
    if TODO_FILE.exists():
        return json.loads(TODO_FILE.read_text())
    return []

def save_todos(todos):
    TODO_FILE.write_text(json.dumps(todos, indent=2))

def cmd_add(text):
    todos = load_todos()
    todos.append({"text": text, "done": False})
    save_todos(todos)
    print(f"Added: {text}")

def cmd_list():
    todos = load_todos()
    if not todos:
        print("No todos.")
        return
    for i, t in enumerate(todos, 1):
        mark = "✓" if t["done"] else " "
        print(f"  [{mark}] {i}. {t['text']}")

def cmd_complete(idx):
    todos = load_todos()
    try:
        todos[idx - 1]["done"] = True
    except IndexError:
        print(f"Error: no todo #{idx}")
        sys.exit(1)
    save_todos(todos)
    print(f"Completed: {todos[idx - 1]['text']}")

def cmd_delete(idx):
    todos = load_todos()
    try:
        removed = todos.pop(idx - 1)
    except IndexError:
        print(f"Error: no todo #{idx}")
        sys.exit(1)
    save_todos(todos)
    print(f"Deleted: {removed['text']}")

def main():
    if len(sys.argv) < 2:
        print("Usage: todo.py <add|list|complete|delete> [args]")
        sys.exit(1)

    cmd = sys.argv[1]
    if cmd == "add" and len(sys.argv) > 2:
        cmd_add(" ".join(sys.argv[2:]))
    elif cmd == "list":
        cmd_list()
    elif cmd == "complete" and len(sys.argv) > 2:
        cmd_complete(int(sys.argv[2]))
    elif cmd == "delete" and len(sys.argv) > 2:
        cmd_delete(int(sys.argv[2]))
    else:
        print(f"Unknown command or missing args: {cmd}")
        sys.exit(1)

if __name__ == "__main__":
    main()
